// Some portions generated by Claude
/** Shapes shared by the graph explorer's state, panels and queries. */
import type { Facet } from "./graph-facets.ts";
import type { SparqlTerm } from "./rdf-terms.ts";
import type { Graph, GraphNode, GraphTransform } from "./graph-types.ts";

export type Direction = "outgoing" | "incoming";

export type SparqlValue = SparqlTerm;

export type Binding = Record<string, SparqlValue | undefined>;

export type SparqlResponse = {
  head?: { vars?: string[] };
  results?: { bindings?: Binding[] };
  boolean?: boolean;
};

export type FilterFacetValue = {
  id: string;
  label: string;
  count: number;
  node?: GraphNode;
  visual: { stroke: string; fill: string };
};

export type RangeDraft = { from: string; to: string };

export type FilterFacet = Omit<Facet, "values"> & {
  values: FilterFacetValue[];
  maxCount: number;
  endpointQueryable: boolean;
};

export type PredicateOption = {
  predicate: string;
  label: string;
  direction: Direction;
  count: number | null;
};

export type ContextMenu = {
  node: GraphNode;
  /** What the menu acts on: the node it was opened on, or the selection that node is part of. */
  scopeNodeIds: string[];
  nodeIds: string[];
  x: number;
  y: number;
  openedAt: number;
  phase: "idle" | "loading" | "ready" | "error";
  predicates: PredicateOption[];
  error?: string;
};

export type ViewMode =
  | "graph"
  | "table"
  | "cards"
  | "matrix"
  | "timeline"
  | "map"
  | "chart";

export type LoadBatch = {
  id: string;
  label: string;
  endpoint: string;
  query: string;
  tripleCount: number;
  loadedAt: string;
  limit: number | null;
  complete: boolean;
};

export type NamedGroup = {
  id: string;
  name: string;
  nodeIds: string[];
  color: string;
};

export type GraphHistorySnapshot = {
  graph: Graph;
  provenanceBatches: LoadBatch[];
  transform: GraphTransform;
  selectedNodeIds: string[];
  focusedNodeId: string | null;
  namedGroups: NamedGroup[];
  /** The filters (facet id → value ids) and their range texts: Undo puts back what was selected. */
  facetValues: Array<[string, string[]]>;
  rangeDrafts: Array<[string, RangeDraft]>;
};

export type EndpointFacetValue = {
  id: string;
  label: string;
  count: number;
};

export type LayoutIntent =
  | {
      mode: "incremental";
      revision: number;
      anchorId: string;
      previousNodeIds: Set<string>;
      startTransform: GraphTransform;
    }
  | {
      mode: "replace";
      revision: number;
      initialViewport?: {
        nodeId: string;
        scale: number;
      };
    };
